.card-header { margin-bottom: 2rem; }

.card-header h1 {
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
  line-height: 1.2;
}

.card-header p {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: .9375rem;
}

