#contact-form { display: flex; flex-direction: column; gap: 1.25rem; }

/* ── form-field wrapper ───────────────────────────────── */
.form-field { display: flex; flex-direction: column; gap: .375rem; }

/* ── Label row ────────────────────────────────────────── */
.field-label-row {
  display: flex;
  align-items: baseline;
  gap: .375rem;
}

.field-label {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-label);
  cursor: pointer;
