  border-radius: var(--radius);
  color: #fff;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: .01em;
  padding: .8125rem 1.5rem;
  transition: background var(--transition), transform 80ms ease, box-shadow var(--transition);
  width: 100%;
  outline: none;
}

.submit-btn:hover { background: var(--color-accent-hover); }

.submit-btn:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px rgba(108,138,255,.25);
