+/* ── Reset & base ─────────────────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --color-bg:           #0f1117;
+  --color-surface:      #1a1d27;
+  --color-surface-2:    #22263a;
+  --color-border:       #2e3350;
+  --color-border-focus: #6c8aff;
+  --color-text:         #e2e5f1;
+  --color-text-muted:   #8891b2;
+  --color-label:        #b4bcd8;
+  --color-accent:       #6c8aff;
+  --color-accent-hover: #8aa3ff;
+  --color-error:        #ff6b6b;
+  --color-error-bg:     rgba(255,107,107,.08);
+  --color-success:      #4ade80;
+  --radius:             8px;
+  --transition:         160ms ease;
+}
+
+html { font-size: 16px; }
+
+body {
+  background: var(--color-bg);
+  color: var(--color-text);
+  font-family: 'Inter', system-ui, -apple-system, sans-serif;
+  line-height: 1.6;
+  min-height: 100vh;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  padding: 2rem 1rem;
+}
+
+/* ── Skip link ────────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -100%;
+  left: 1rem;
+  background: var(--color-accent);
+  color: #fff;
+  padding: .5rem 1rem;
+  border-radius: var(--radius);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 9999;
+  transition: top var(--transition);
+}
+.skip-link:focus { top: 1rem; }
+
+/* ── Page wrapper ─────────────────────────────────────── */
+.page-wrapper {
+  width: 100%;
+  max-width: 520px;
+}
+
+/* ── Card ─────────────────────────────────────────────── */
+.card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: 16px;
+  padding: 2.5rem 2rem;
+}
+
+/* ── Header ───────────────────────────────────────────── */
+.card-header { margin-bottom: 2rem; }
